  // TC-017 preview 价格（选项加价由服务端重算）
  const preview = await api('POST', '/api/v1/orders/preview', {
    token: emp.token,
    body: { items: [{ dishId: burger.id, qty: 1, optionIds: [] }], deliveryDate: new Date().toISOString().slice(0, 10), mealType: 'LUNCH', address: 'Office 1F, Test Street' },
  });
