GROUP BY action, object_type;

SELECT '=== 10. 今日订单状态分布（TC-065 看板对账）===' AS section;
SELECT status, COUNT(*) AS cnt, COALESCE(SUM(total_cents),0) AS revenue_cents
FROM orders
WHERE delivery_date = CURDATE()
GROUP BY status;

